#!/usr/bin/env node
// verify-identity-attestation.mjs — offline persona identity check (task #1002).
//
// CANONICAL SOURCE: o-matic-studio/scripts/verify-identity-attestation.mjs.
// Copies in o-matic-firm and o-matic-agency are generated by
// scripts/sync-pack-tooling.mjs; its --check fails on drift.
//
// WHY THIS EXISTS. The release CI step that compared a pack against the live
// Spirit Gate (scripts/spirit-gate-check.mjs) could never run where CI runs: it
// needs a token for, and a route into, a tailnet-only server that a GitHub
// runner has no business reaching (Smith #1013 RC-1, "context blindness"). A
// gate that cannot run is red on every push, and a gate that is always red
// teaches everyone to ignore it.
//
// So CI checks what it CAN check deterministically, with no network: every
// shipped SKILL.md that declares an `identity_signature` must declare exactly
// the signature the gold record carries, as exported into the committed
// persona-attestation.json (schema 2). A skill that declares none must be
// recorded as `declares_identity: false` — absence is written down, never
// assumed. The live comparison stays as the LOCAL pre-release step
// (spirit-gate-check.mjs), which is where the server can actually be reached.
//
// The attestation is exported from the factory record by
// scripts/persona-attest-export.sql through the o-MATIC Server. This script
// never connects to anything.
//
// Usage: node scripts/verify-identity-attestation.mjs <marketplace-root>
//        (--attestation <file> overrides the attestation path, for fixtures)
import { readFileSync, readdirSync, statSync, lstatSync, existsSync } from "node:fs";
import { join, basename } from "node:path";

const args = process.argv.slice(2);
const root = args.find((a) => !a.startsWith("--"));
if (!root) { console.error("usage: verify-identity-attestation.mjs <marketplace-root> [--attestation <file>]"); process.exit(2); }
const ai = args.indexOf("--attestation");
const attPath = ai >= 0 ? args[ai + 1] : join(root, "persona-attestation.json");

let fails = 0, checks = 0;
const FAIL = (m) => { console.log(`  FAIL  ${m}`); fails++; };
const OK = (m) => console.log(`  ok    ${m}`);
const walk = (d) => readdirSync(d).flatMap((f) => {
  const p = join(d, f);
  if (f === ".git" || f === "node_modules" || lstatSync(p).isSymbolicLink()) return [];
  return statSync(p).isDirectory() ? walk(p) : [p];
});
const SIG = /identity_signature:\s*([0-9a-f]{32})\b/;
const HEX32 = /^[0-9a-f]{32}$/;

console.log(`\n=== identity attestation (offline) — ${root} ===\n`);

let att;
if (!existsSync(attPath)) FAIL(`${attPath} missing — no committed record of which identities this pack may ship`);
else {
  try { att = JSON.parse(readFileSync(attPath, "utf8")); }
  catch (e) { FAIL(`${attPath} is not valid JSON: ${e.message}`); }
}
if (att) {
  if (att.schema !== 2) FAIL(`persona-attestation.json is schema ${att.schema ?? 1}; schema 2 carries the signature strings this check compares — re-export with scripts/persona-attest-export.sql`);
  if (!att.generated_at || !att.tenant) FAIL("persona-attestation.json has no generated_at/tenant provenance");
  const bySkill = new Map((att.personas ?? []).map((p) => [p.skill, p]));
  for (const f of walk(root).filter((p) => basename(p) === "SKILL.md")) {
    checks++;
    const skill = basename(f.replace(/\/SKILL\.md$/, ""));
    const declared = (readFileSync(f, "utf8").match(SIG) || [])[1] || null;
    const rec = bySkill.get(skill);
    if (!rec) { FAIL(`${skill}: not in persona-attestation.json`); continue; }
    if (rec.declares_identity === false) {
      if (declared) FAIL(`${skill}: declares identity_signature ${declared} but the attestation records it as declaring none — re-export or remove the header`);
      else OK(`${skill}: declares no identity, as attested (lane of '${rec.agent_name}')`);
      continue;
    }
    if (typeof rec.identity_signature !== "string" || !HEX32.test(rec.identity_signature)) {
      FAIL(`${skill}: attestation carries no signature string for '${rec.agent_name}'`);
      continue;
    }
    if (!declared) { FAIL(`${skill}: declares no identity_signature; the attestation expects ${rec.identity_signature}`); continue; }
    if (declared !== rec.identity_signature)
      FAIL(`${skill}: declares ${declared}, but the '${rec.agent_name}' gold record (v${rec.version}) is ${rec.identity_signature} — the shipped identity is not the certified one`);
    else OK(`${skill}: identity_signature ${declared} matches the '${rec.agent_name}' gold record (v${rec.version})`);
  }
}

console.log(`\n${fails ? "RESULT: FAIL" : "RESULT: PASS"} — ${checks} skill(s) checked, ${fails} fail\n`);
process.exit(fails ? 1 : 0);
